test:
words = ['wrt', 'wrf', 'er', 'ett', 'rftt']
order = alien_order(words)
assert isinstance(order, str), "Return a string"
characters = set("".join(words))
assert len(order) == len(characters) and set(order) == characters, "Include every distinct character exactly once"
position = {char: index for index, char in enumerate(order)}
for first, second in zip(words, words[1:]):
    for left, right in zip(first, second):
        if left != right:
            assert position[left] < position[right], f"{left} must precede {right}"
            break
    else:
        assert len(first) <= len(second), "A longer word cannot precede its prefix"

